wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1816027050328854)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Course CRUD Test Harness'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  c_marker CONSTANT VARCHAR2(60) := ''QAFE CRUD TEST - QAFE_FORMS_BUILDER'';',
'  l_count PLS_INTEGER;',
'  l_now DATE;',
'BEGIN',
'  IF :APP_USER <> ''QAFE_FORMS_BUILDER'' THEN',
'    raise_application_error(-20081, ''Only the local CRUD test owner may change the test fixture.'');',
'  END IF;',
'',
'  IF :REQUEST = ''CREATE'' THEN',
'    SELECT COUNT(*) INTO l_count',
'      FROM course',
'     WHERE description = c_marker',
'       AND created_by = ''QAFE_FORMS_BUILDER'';',
'    IF l_count <> 0 THEN',
'      raise_application_error(-20082, ''A CRUD test fixture already exists.'');',
'    END IF;',
'',
'    l_now := SYSDATE;',
'    :P6_COURSE_NO := course_no_seq.NEXTVAL;',
'    :P6_DESCRIPTION := c_marker;',
'    :P6_CREATED_BY := :APP_USER;',
'    :P6_CREATED_DATE := l_now;',
'    :P6_MODIFIED_BY := :APP_USER;',
'    :P6_MODIFIED_DATE := l_now;',
'',
'    INSERT INTO course (',
'      course_no, description, cost, prerequisite,',
'      created_by, created_date, modified_by, modified_date',
'    ) VALUES (',
'      :P6_COURSE_NO, c_marker, :P6_COST, :P6_PREREQUISITE,',
'      :APP_USER, l_now, :APP_USER, l_now',
'    );',
'  ELSIF :REQUEST = ''SAVE'' THEN',
'    l_now := SYSDATE;',
'    UPDATE course',
'       SET cost = :P6_COST,',
'           prerequisite = :P6_PREREQUISITE,',
'           modified_by = :APP_USER,',
'           modified_date = l_now',
'     WHERE course_no = TO_NUMBER(:P6_COURSE_NO)',
'       AND description = c_marker',
'       AND created_by = ''QAFE_FORMS_BUILDER'';',
'    IF SQL%ROWCOUNT <> 1 THEN',
'      raise_application_error(-20083, ''Only the active CRUD test fixture can be updated.'');',
'    END IF;',
'  ELSIF :REQUEST = ''DELETE'' THEN',
'    DELETE FROM course',
'     WHERE course_no = TO_NUMBER(:P6_COURSE_NO)',
'       AND description = c_marker',
'       AND created_by = ''QAFE_FORMS_BUILDER'';',
'    IF SQL%ROWCOUNT <> 1 THEN',
'      raise_application_error(-20084, ''Only the active CRUD test fixture can be deleted.'');',
'    END IF;',
'    :P6_COURSE_NO := NULL;',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Temporary CRUD test operation completed.'
,p_security_scheme=>wwv_flow_imp.id(1816703897365539)
,p_internal_uid=>1816027050328854
);
