wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1833152619773673)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Maintain Instructor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_now DATE := SYSDATE;',
'  l_section_count PLS_INTEGER;',
'BEGIN',
'  IF :APP_USER <> ''QAFE_FORMS_BUILDER'' THEN',
'    raise_application_error(-20091, ''Only QAFE_FORMS_BUILDER may maintain local Form 2 data.'');',
'  END IF;',
'',
'  IF :REQUEST = ''CREATE'' THEN',
'    :P8_INSTRUCTOR_ID := instructor_id_seq.NEXTVAL;',
'    :P8_CREATED_BY := :APP_USER;',
'    :P8_CREATED_DATE := l_now;',
'    :P8_MODIFIED_BY := :APP_USER;',
'    :P8_MODIFIED_DATE := l_now;',
'    INSERT INTO instructor (',
'      instructor_id, salutation, first_name, last_name, street_address, zip, phone,',
'      created_by, created_date, modified_by, modified_date',
'    ) VALUES (',
'      :P8_INSTRUCTOR_ID, :P8_SALUTATION, :P8_FIRST_NAME, :P8_LAST_NAME,',
'      :P8_STREET_ADDRESS, :P8_ZIP, :P8_PHONE,',
'      :APP_USER, l_now, :APP_USER, l_now',
'    );',
'  ELSIF :REQUEST = ''SAVE'' THEN',
'    UPDATE instructor',
'       SET salutation = :P8_SALUTATION,',
'           first_name = :P8_FIRST_NAME,',
'           last_name = :P8_LAST_NAME,',
'           street_address = :P8_STREET_ADDRESS,',
'           zip = :P8_ZIP,',
'           phone = :P8_PHONE,',
'           modified_by = :APP_USER,',
'           modified_date = l_now',
'     WHERE instructor_id = TO_NUMBER(:P8_INSTRUCTOR_ID);',
'    IF SQL%ROWCOUNT <> 1 THEN',
'      raise_application_error(-20092, ''Instructor not found or could not be updated.'');',
'    END IF;',
'  ELSIF :REQUEST = ''DELETE'' THEN',
'    SELECT COUNT(*) INTO l_section_count',
'      FROM section',
'     WHERE instructor_id = TO_NUMBER(:P8_INSTRUCTOR_ID);',
'    IF l_section_count > 0 THEN',
'      raise_application_error(-20093, ''Cannot delete an instructor referenced by a section.'');',
'    END IF;',
'    DELETE FROM instructor',
'     WHERE instructor_id = TO_NUMBER(:P8_INSTRUCTOR_ID);',
'    IF SQL%ROWCOUNT <> 1 THEN',
'      raise_application_error(-20094, ''Instructor not found or could not be deleted.'');',
'    END IF;',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_security_scheme=>wwv_flow_imp.id(1818666702754940)
,p_internal_uid=>1833152619773673
);
